-- Build 259 read-only verification.
SELECT migration_key,status,applied_at FROM schema_migration_ledger WHERE migration_key='build259_media_static_slot_catalog';
SELECT COUNT(*) AS active_static_slots FROM media_content_slots WHERE is_active=1 AND page_path IN ('/','/about','/collections','/contact','/creations','/custom-candle-making-ontario','/custom-gifts-southern-ontario','/custom-soap-making-ontario','/data-deletion','/events','/gallery','/gift-cards','/handmade-jewelry-ontario','/laser-engraving-ontario','/marketplaces','/movies','/pickup','/polymer-clay-earrings-ontario','/privacy','/social-connections','/socials','/terms','/vintage-finds-ontario','/workshop-journal','/workshop-journal/coin-and-spoon-ring-care','/workshop-journal/handmade-vintage-sourced-guide','/workshop-journal/polymer-clay-earring-care','/workshop-journal/story','/workshop-made-gifts-ontario','@site');
SELECT slot_type,COUNT(*) AS count FROM media_content_slots WHERE is_active=1 AND page_path IN ('/','/about','/collections','/contact','/creations','/custom-candle-making-ontario','/custom-gifts-southern-ontario','/custom-soap-making-ontario','/data-deletion','/events','/gallery','/gift-cards','/handmade-jewelry-ontario','/laser-engraving-ontario','/marketplaces','/movies','/pickup','/polymer-clay-earrings-ontario','/privacy','/social-connections','/socials','/terms','/vintage-finds-ontario','/workshop-journal','/workshop-journal/coin-and-spoon-ring-care','/workshop-journal/handmade-vintage-sourced-guide','/workshop-journal/polymer-clay-earring-care','/workshop-journal/story','/workshop-made-gifts-ontario','@site') GROUP BY slot_type ORDER BY slot_type;
SELECT page_path,COUNT(*) AS slot_count FROM media_content_slots WHERE is_active=1 AND page_path IN ('/','/about','/collections','/contact','/creations','/custom-candle-making-ontario','/custom-gifts-southern-ontario','/custom-soap-making-ontario','/data-deletion','/events','/gallery','/gift-cards','/handmade-jewelry-ontario','/laser-engraving-ontario','/marketplaces','/movies','/pickup','/polymer-clay-earrings-ontario','/privacy','/social-connections','/socials','/terms','/vintage-finds-ontario','/workshop-journal','/workshop-journal/coin-and-spoon-ring-care','/workshop-journal/handmade-vintage-sourced-guide','/workshop-journal/polymer-clay-earring-care','/workshop-journal/story','/workshop-made-gifts-ontario','@site') GROUP BY page_path ORDER BY page_path;
SELECT COUNT(*) AS blocked_product_inventory_slots FROM media_content_slots WHERE is_active=1 AND (page_path LIKE '/shop%' OR page_path LIKE '/tools%' OR page_path LIKE '/toolshed%' OR page_path LIKE '/supplies%' OR page_path LIKE '/admin%');
